def compare_versions(a: str, b: str) -> int:
    def parse_version(version_str):
        # Split off build metadata (everything after +)
        if '+' in version_str:
            version_str = version_str.split('+')[0]

        # Split off pre-release (everything after -)
        if '-' in version_str:
            main_part, prerelease_part = version_str.split('-', 1)
            prerelease = prerelease_part.split('.')
        else:
            main_part = version_str
            prerelease = None

        # Parse major.minor.patch
        parts = main_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return major, minor, patch, prerelease

    def compare_prerelease(pre_a, pre_b):
        # If both have no pre-release, they're equal (on this criterion)
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                # pre_a has fewer identifiers, so it has lower precedence
                return -1
            if i >= len(pre_b):
                # pre_b has fewer identifiers, so pre_a has higher precedence
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            if is_numeric_a and is_numeric_b:
                # Both numeric: compare as integers
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_numeric_a:
                # Only id_a is numeric: numeric identifiers have lower precedence
                return -1
            elif is_numeric_b:
                # Only id_b is numeric: id_a is non-numeric, so higher precedence
                return 1
            else:
                # Both non-numeric: compare as strings
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
